            self.l = l
            self.r = r
            self.left = None
            self.right = None
            self.balance = 0
            self.min_balance = 0

    def build(l, r):
        node = SegmentTreeNode(l, r)
        if l == r:
            node.balance = s[l-1]
            node.min_balance = s[l-1]
        else:
            mid = (l + r) // 2
            node.left = build(l, mid)
            node.right = build(mid+1, r)
            node.balance = node.left.balance + node.right.balance
            node.min_balance = min(node.left.min_balance, node.left.balance + node.right.min_balance)
        return node

    def update(node, pos, val):
        if node.l == node.r:
            node.balance = val
            node.min_balance = val
        else:
            if pos <= node.left.r:
                update(node.left, pos, val)
            else:
                update(node.right, pos, val)
            node.balance = node.left.balance + node.right.balance
            node.min_balance = min(node.left.min_balance, node.left.balance + node.right.min_balance)

    def query(node, l, r):
        if node.r < l or node.l > r:
            return 0, float('inf')
        if l <= node.l and node.r <= r:
            return node.balance, node.min_balance
        left_bal, left_min = query(node.left, l, r)
        right_bal, right_min = query(node.right, l, r)
        if node.left.r < l:
            return right_bal, right_min
        if node.right.l > r:
            return left_bal, left_min
        return left_bal + right_bal, min(left_min, left_bal + right_min)

    root = build(1, n)

    for query_type, *args in queries:
        if query_type == 1:
            i, t = args
            update(root, i, t)
            s[i-1] = t
        else:
            l, r = args
            total, min_bal = query(root, l, r)
            if total == 0 and min_bal >= 0:
                print("Yes")
            else:
                print("No")

if __name__ == "__main__":
    main()
